{"path": "/home/daytona/cleanup_sandboxes.py", "content": "from daytona import Daytona

def main():
    daytona = Daytona()
    result = daytona.list()
    print(f"Found {len(result.items)} sandboxes:")
    for sb in result.items:
        print(f"  - ID: {sb.id}, State: {sb.state}")
        if sb.state.value == "stopped":
            print(f"    -> Deleting stopped sandbox...")
            daytona.delete(sb.id)
            print(f"    -> Deleted.")

if __name__ == "__main__":
    main()
"}

